static const z_t6425_t _zag3111 = { { .data = "win_wide", .size = 8 }, { .length = 1, .data = _zag3109 }, { .length = 1, .data = _zag3110 }, { .data = "static wchar_t* z_win_wide(const char* s, size_t n) {\n    if (n > (size_t)INT_MAX) {\n        SetLastError(ERROR_FILENAME_EXCED_RANGE);\n        return NULL;\n    }\n    int wn = 0;\n    if (n > 0) {\n        wn = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, s, (int)n, NULL, 0);\n        if (wn == 0) return NULL;\n    }\n    wchar_t* w = (wchar_t*)z_xmalloc(((size_t)wn + 1) * sizeof(wchar_t));\n    if (n > 0) MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, s, (int)n, w, wn);\n    w[wn] = 0;\n    return w;\n}", .size = 509 } };
