static const z_t6425_t _zag3128 = { { .data = "win_write", .size = 9 }, { .length = 1, .data = _zag3127 }, { .length = 0, .data = NULL }, { .data = "static int64_t z_win_write(int fd, const void* buf, uint64_t n) {\n    DWORD put = 0;\n    DWORD ask = n > 0x40000000u ? 0x40000000u : (DWORD)n;\n    if (!WriteFile((HANDLE)_get_osfhandle(fd), buf, ask, &put, NULL)) return -1;\n    return (int64_t)put;\n}", .size = 250 } };
